<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Opportunity; use App\Models\SavedOpportunity; use App\Models\OcdNotification; use App\Models\OpportunityReviewLog; use App\Models\Report; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class MemberToolsController extends Controller {
 public function saved(Request $r) { return response()->json(['data'=>SavedOpportunity::with('opportunity')->where('user_id',$r->user()->id)->latest()->paginate(20)]); }
 public function save(Request $r,int $opportunity) { $o=Opportunity::where('status','published')->findOrFail($opportunity); $row=SavedOpportunity::firstOrCreate(['user_id'=>$r->user()->id,'opportunity_id'=>$o->id]); return response()->json(['message'=>'Opportunité enregistrée dans vos favoris.','data'=>$row],$row->wasRecentlyCreated?201:200); }
 public function unsave(Request $r,int $opportunity) { SavedOpportunity::where('user_id',$r->user()->id)->where('opportunity_id',$opportunity)->delete(); return response()->json(['message'=>'Opportunité retirée des favoris.']); }
 public function notifications(Request $r) { return response()->json(['data'=>$r->user()->ocdNotifications()->latest()->paginate(30),'unread_count'=>$r->user()->ocdNotifications()->whereNull('read_at')->count()]); }
 public function markRead(Request $r,int $notification) { $n=$r->user()->ocdNotifications()->findOrFail($notification); $n->update(['read_at'=>now()]); return response()->json(['message'=>'Notification marquée comme lue.']); }
 public function report(Request $r) { $d=$r->validate(['type'=>['required','in:opportunity,profile'],'id'=>['required','integer','min:1'],'reason'=>['required','in:fraud,misleading,expired,inappropriate,impersonation,other'],'details'=>['nullable','string','max:3000']]); if($d['type']==='opportunity') Opportunity::where('status','published')->findOrFail($d['id']); else abort(422,'Le signalement de profil sera activé dans un bloc ultérieur.'); $existing=Report::where('reporter_id',$r->user()->id)->where('reportable_type',$d['type'])->where('reportable_id',$d['id'])->where('status','pending')->exists(); if($existing)return response()->json(['message'=>'Un signalement est déjà en cours pour ce contenu.'],409); $report=Report::create(['reporter_id'=>$r->user()->id,'reportable_type'=>$d['type'],'reportable_id'=>$d['id'],'reason'=>$d['reason'],'details'=>$d['details']??null]); return response()->json(['message'=>'Signalement transmis à l’équipe OCD.','data'=>$report],201); }
 public function reportQueue() { return response()->json(['data'=>Report::with('reporter:id,name,email')->where('status','pending')->latest()->paginate(30)]); }
 public function resolveReport(Request $r,int $report) { $d=$r->validate(['decision'=>['required','in:dismissed,action_taken'],'note'=>['required','string','max:2000']]); $item=Report::findOrFail($report); DB::transaction(function() use($r,$d,$item){ $item->update(['status'=>$d['decision'],'reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'review_note'=>$d['note']]); if($d['decision']==='action_taken' && $item->reportable_type==='opportunity'){ $o=Opportunity::find($item->reportable_id); if($o && $o->status==='published'){ $o->update(['status'=>'suspended','published_at'=>null]); OpportunityReviewLog::create(['opportunity_id'=>$o->id,'reviewer_id'=>$r->user()->id,'action'=>'suspended_report','note'=>$d['note']]); OcdNotification::create(['user_id'=>$o->user_id,'type'=>'opportunity_suspended','title'=>'Opportunité suspendue','message'=>'Une annonce a été suspendue après examen d’un signalement. Consultez votre espace pour plus de détails.','data'=>['opportunity_id'=>$o->id]]); } } }); return response()->json(['message'=>'Signalement traité.','data'=>$item->fresh()]); }
}
